function getLangText(textObject) {
return textObject[Lang.get()];
}
for (const [key, val] of Object.entries(Text)) {
if (typeof val === "function") {
Text[key] = function () {
return getLangText(val(...arguments));
};
} else {
Object.defineProperty(Text, key, {
get: () => getLangText(val),
});
}
}
Object.freeze(Text);
